import { useState, useEffect, useRef } from 'react';

// Speech configuration for different scenarios
export interface SpeechConfig {
  id: string;
  text: string;
  rate?: number;
  pitch?: number;
  volume?: number;
  voice?: string;
}

// Speech scenarios configuration
export const SPEECH_SCENARIOS: Record<string, Record<string, SpeechConfig[]>> = {
  norton: {
    normal: [
      {
        id: 'norton_normal_1',
        text: "Warning! Your Norton subscription has expired. Your device is no longer protected. Multiple threats have been detected. Renew your subscription immediately to restore protection.",
        rate: 0.9,
        pitch: 1.1,
        volume: 0.8
      }
    ],
    escalation: [
      {
        id: 'norton_escalation_1',
        text: "CRITICAL ALERT! Your system has been compromised! Multiple threats are actively stealing your data! System meltdown is imminent! You must renew Norton immediately or lose everything!",
        rate: 1.1,
        pitch: 1.3,
        volume: 0.8
      }
    ]
  },
  microsoft: {
    normal: [
      {
        id: 'microsoft_normal_1',
        text: "Your Windows system has been compromised by malware. Immediate action required. Call Microsoft Support now to prevent data loss.",
        rate: 0.9,
        pitch: 1.0,
        volume: 0.8
      }
    ],
    escalation: [
      {
        id: 'microsoft_escalation_1',
        text: "EMERGENCY! Your computer is under attack! Malware is stealing your passwords and personal information! Call Microsoft immediately!",
        rate: 1.2,
        pitch: 1.2,
        volume: 0.8
      }
    ]
  },
  google: {
    normal: [
      {
        id: 'google_normal_1',
        text: "Your Google account has been compromised. Unauthorized access detected. Verify your identity immediately.",
        rate: 0.9,
        pitch: 1.0,
        volume: 0.8
      }
    ],
    escalation: [
      {
        id: 'google_escalation_1',
        text: "URGENT! Your Google account is being hacked! Personal data is being stolen! Verify your identity now!",
        rate: 1.1,
        pitch: 1.2,
        volume: 0.8
      }
    ]
  }
};

export const useGlobalAudio = () => {
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentScenario, setCurrentScenario] = useState<string>('');
  const [currentMode, setCurrentMode] = useState<'normal' | 'escalation'>('normal');
  
  const speechTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  const currentSpeechRef = useRef<SpeechSynthesisUtterance | null>(null);

  // Function to force stop all speech
  const forceStopSpeech = () => {
    console.log(`🔇 Global Audio: Force stopping all speech`);
    // Cancel all speech synthesis
    speechSynthesis.cancel();
    
    // Clear any speech timeouts
    if (speechTimeoutRef.current) {
      clearTimeout(speechTimeoutRef.current);
      speechTimeoutRef.current = null;
    }
    
    // Clear current speech reference
    currentSpeechRef.current = null;
    
    setIsPlaying(false);
  };

  // Function to start speech for a specific scenario and mode
  const startSpeech = (scenario: string, mode: 'normal' | 'escalation' = 'normal') => {
    console.log(`🔊 Global Audio: Starting speech for ${scenario} (${mode})`);
    
    // Always stop any existing speech first (immediate transition)
    forceStopSpeech();
    
    const scenarios = SPEECH_SCENARIOS[scenario];
    if (!scenarios || !scenarios[mode as keyof typeof scenarios] || scenarios[mode as keyof typeof scenarios].length === 0) {
      console.log(`⚠️ Global Audio: No speech config found for ${scenario} (${mode})`);
      return;
    }

    const speechConfig = scenarios[mode as keyof typeof scenarios][0]; // Use first speech config for now
    const speech = new SpeechSynthesisUtterance();
    
    speech.text = speechConfig.text;
    speech.rate = speechConfig.rate || 1.0;
    speech.pitch = speechConfig.pitch || 1.0;
    speech.volume = speechConfig.volume || 0.8;
    
    // Try to use a more authoritative voice if available
    const voices = speechSynthesis.getVoices();
    const preferredVoice = voices.find(voice => 
      voice.name.includes('Microsoft') || 
      voice.name.includes('David') || 
      voice.name.includes('Mark') ||
      voice.name.includes('James')
    );
    if (preferredVoice) {
      speech.voice = preferredVoice;
    }
    
    // Speech ends - no automatic looping to avoid infinite loops
    speech.onend = () => {
      console.log(`🔊 Global Audio: Speech ended for ${scenario} (${mode})`);
      // Clear the current speech reference
      currentSpeechRef.current = null;
    };
    
    currentSpeechRef.current = speech;
    setCurrentScenario(scenario);
    setCurrentMode(mode);
    setIsPlaying(true);
    
    console.log(`🔊 Global Audio: Speaking: "${speechConfig.text.substring(0, 50)}..."`);
    // Start speaking immediately
    speechSynthesis.speak(speech);
  };

  // Function to stop speech
  const stopSpeech = () => {
    forceStopSpeech();
    setCurrentScenario('');
    setCurrentMode('normal');
  };

  // Function to toggle speech on/off
  const toggleSpeech = () => {
    console.log(`🔄 Global Audio: Toggle speech - currently playing: ${isPlaying}, scenario: ${currentScenario}`);
    if (isPlaying) {
      stopSpeech();
    } else if (currentScenario) {
      // Resume speech for current scenario
      startSpeech(currentScenario, currentMode);
    }
  };

  // Function to change scenario
  const changeScenario = (scenario: string, mode: 'normal' | 'escalation' = 'normal') => {
    if (isPlaying) {
      startSpeech(scenario, mode);
    } else {
      setCurrentScenario(scenario);
      setCurrentMode(mode);
    }
  };

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      forceStopSpeech();
    };
  }, []);

  return {
    isPlaying,
    currentScenario,
    currentMode,
    startSpeech,
    stopSpeech,
    toggleSpeech,
    changeScenario,
    forceStopSpeech
  };
};
